WITH metrics AS (SELECT *, ROW_NUMBER() OVER (ORDER BY starts_on, id) AS seq_no, AVG(discount_pct) OVER (PARTITION BY promo_code, channel ORDER BY starts_on, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS discount_pct_avg_2, SUM(discount_pct) OVER (PARTITION BY channel, promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct FROM promotions) SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, discount_pct_avg_2, running_discount_pct, CASE WHEN channel RLIKE '^(web|partner)$' THEN 'OTHER_ZONE' WHEN channel RLIKE '^(mobile|store)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS channel_zone FROM metrics ORDER BY id DESC, promo_code DESC LIMIT 10;
